<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class UpbringingIntegrationController extends Controller{
private function staff(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('upbringing_head')||$r->user()->hasRole('curator')||$r->user()->hasRole('psychologist')||$r->user()->hasRole('social_teacher'),403);}
private function head(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('upbringing_head'),403);}
public function student(Request $r,$student){$this->staff($r);$p=$r->attributes->get('academic_period');$s=DB::table('students')->find($student);abort_if(!$s,404);$membership=DB::table('student_group_memberships as m')->join('study_groups as g','g.id','=','m.study_group_id')->where(['m.student_id'=>$student,'m.academic_period_id'=>$p->id])->select('m.*','g.name as group_name')->first();$cases=DB::table('student_support_cases')->where(['academic_period_id'=>$p->id,'student_id'=>$student])->orderByDesc('id')->get();$achievements=DB::table('student_achievements')->where(['academic_period_id'=>$p->id,'student_id'=>$student])->orderByDesc('achieved_on')->get();$events=DB::table('upbringing_event_participants as ep')->join('upbringing_events as e','e.id','=','ep.upbringing_event_id')->where('ep.student_id',$student)->where('e.academic_period_id',$p->id)->select('e.title','e.starts_at','e.direction','ep.role','ep.attended')->orderByDesc('e.starts_at')->get();$clubs=DB::table('student_club_members as m')->join('student_clubs as c','c.id','=','m.student_club_id')->where('m.student_id',$student)->where('c.academic_period_id',$p->id)->select('c.title','c.type','m.role','m.joined_on','m.left_on')->get();$volunteer=DB::table('volunteer_records')->where(['academic_period_id'=>$p->id,'student_id'=>$student])->orderByDesc('activity_on')->get();$recommendations=collect();if($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('upbringing_head')||$r->user()->hasRole('psychologist')||$r->user()->hasRole('social_teacher'))$recommendations=DB::table('specialist_consultations')->where(['academic_period_id'=>$p->id,'student_id'=>$student])->whereNotNull('shared_recommendation')->select('consulted_at','specialist_type','shared_recommendation','follow_up_on')->orderByDesc('consulted_at')->get();return view('upbringing.student-card',compact('s','membership','cases','achievements','events','clubs','volunteer','recommendations'));}
public function documents(Request $r){$this->head($r);$p=$r->attributes->get('academic_period');$rows=DB::table('upbringing_document_links as l')->join('official_documents as d','d.id','=','l.official_document_id')->where('d.academic_period_id',$p->id)->select('l.*','d.number','d.type','d.status','d.created_at')->orderByDesc('d.id')->get();$docs=DB::table('official_documents')->where('academic_period_id',$p->id)->orderByDesc('id')->get();return view('upbringing.documents',compact('rows','docs'));}
public function documentLink(Request $r){$this->head($r);$d=$r->validate(['official_document_id'=>'required|exists:official_documents,id','entity_type'=>'required|in:event,case,council,meeting,task','entity_id'=>'required|integer|min:1','relation'=>'required|in:basis,result,order,protocol']);DB::table('upbringing_document_links')->updateOrInsert(['official_document_id'=>$d['official_document_id'],'entity_type'=>$d['entity_type'],'entity_id'=>$d['entity_id']],['relation'=>$d['relation'],'updated_at'=>now(),'created_at'=>now()]);return back();}
public function notifications(Request $r){$this->staff($r);$this->syncNotifications($r);$rows=DB::table('upbringing_notifications')->where('user_id',$r->user()->id)->orderByRaw('read_at is not null')->orderByDesc('created_at')->limit(100)->get();return view('upbringing.notifications',compact('rows'));}
public function read(Request $r,$id){$this->staff($r);DB::table('upbringing_notifications')->where(['id'=>$id,'user_id'=>$r->user()->id])->update(['read_at'=>now(),'updated_at'=>now()]);return back();}
private function syncNotifications(Request $r){$uid=$r->user()->id;$p=$r->attributes->get('academic_period');$tasks=DB::table('upbringing_tasks')->where(['academic_period_id'=>$p->id,'assigned_to'=>$uid])->whereNotIn('status',['done','cancelled'])->whereNotNull('due_on')->where('due_on','<=',now()->addDays(3)->toDateString())->get();foreach($tasks as $x)$this->notify($uid,'task','Поручение: '.$x->title,'Срок: '.$x->due_on,route('upbringing.tasks'),'task-'.$x->id.'-'.$x->due_on);$cases=DB::table('student_support_cases')->where(['academic_period_id'=>$p->id,'responsible_user_id'=>$uid])->where('status','!=','closed')->whereNotNull('next_contact_on')->where('next_contact_on','<=',now()->addDays(2)->toDateString())->get();foreach($cases as $x)$this->notify($uid,'case','Контроль сопровождения','Контрольная дата: '.$x->next_contact_on,route('upbringing.case',$x->id),'case-'.$x->id.'-'.$x->next_contact_on);}
private function notify($uid,$type,$title,$message,$url,$fp){DB::table('upbringing_notifications')->updateOrInsert(['fingerprint'=>$fp],['user_id'=>$uid,'type'=>$type,'title'=>$title,'message'=>$message,'url'=>$url,'updated_at'=>now(),'created_at'=>now()]);}
public function annual(Request $r){$this->head($r);$p=$r->attributes->get('academic_period');$events=DB::table('upbringing_events')->where('academic_period_id',$p->id)->select('direction',DB::raw('COUNT(*) total'),DB::raw("SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END) completed"),DB::raw('SUM(COALESCE(participants_count,0)) participants'))->groupBy('direction')->get();$stats=['events'=>$events->sum('total'),'completed'=>$events->sum('completed'),'participants'=>$events->sum('participants'),'achievements'=>DB::table('student_achievements')->where('academic_period_id',$p->id)->count(),'cases'=>DB::table('student_support_cases')->where('academic_period_id',$p->id)->count(),'cases_closed'=>DB::table('student_support_cases')->where('academic_period_id',$p->id)->where('status','closed')->count(),'meetings'=>DB::table('parent_meetings')->where('academic_period_id',$p->id)->count(),'councils'=>DB::table('prevention_councils')->where('academic_period_id',$p->id)->count(),'clubs'=>DB::table('student_clubs')->where('academic_period_id',$p->id)->where('active',1)->count(),'appeals'=>DB::table('upbringing_appeals')->where('academic_period_id',$p->id)->count()];return view('upbringing.annual-report',compact('p','events','stats'));}
}